class Solution:
    def maximumHappinessSum(self, happiness: list[int], k: int) -> int:
        happiness.sort(reverse=True)
        result = 0
        for i in range(k):
            val = happiness[i] - i
            if val <= 0:
                break
            result += val
        return result

